/**
 * mesh-bvh implementation (loaded only when features.meshBvh is true).
 * Entry point: mesh-bvh-addon.js (generated by web/scripts/generate-mesh-bvh-addon.mjs).
 */

import { isMeshBvhEnabled } from '/web/features.js';
import {
    Mesh,
    BufferGeometry,
    BufferAttribute,
    Vector3,
    Matrix4,
    Box3,
    Triangle,
    Plane,
    Line3,
    Ray,
    _meshRaycastInternals,
} from '/web/threejs-shim.js';

import { WebMeshBvh, WebBufferGeometry, WebBufferAttribute, mergeGeometries } from '/web/pkg/threers.js';

const _FEATURE_ERR = 'mesh-bvh feature is disabled. Rebuild with: MESH_BVH=1 web/build.sh';

function _requireMeshBvh() {
    if (!isMeshBvhEnabled()) throw new Error(_FEATURE_ERR);
}

// ---- constants (mirror three-mesh-bvh) ----
export const NOT_INTERSECTED = 0;
export const INTERSECTED = 1;
export const CONTAINED = 2;
export const CENTER = 0;
export const AVERAGE = 1;
export const SAH = 2;
export const FrontSide = 0;
export const BackSide = 1;
export const DoubleSide = 2;


/** Minimal Box3 for shapecast callbacks (has .min / .max). */
class BvhBox3 {
    constructor(minX, minY, minZ, maxX, maxY, maxZ) {
        this.min = new Vector3(minX, minY, minZ);
        this.max = new Vector3(maxX, maxY, maxZ);
    }
    intersectsBox(other) {
        return (
            this.min.x <= other.max.x && this.max.x >= other.min.x &&
            this.min.y <= other.max.y && this.max.y >= other.min.y &&
            this.min.z <= other.max.z && this.max.z >= other.min.z
        );
    }
}

function _unpackHit(packed, offset = 0, bvh = null) {
    const faceIndex = packed[offset + 4] | 0;
    const hit = {
        distance: packed[offset],
        point: new Vector3(packed[offset + 1], packed[offset + 2], packed[offset + 3]),
        faceIndex,
        uv: new Vector3(packed[offset + 5], packed[offset + 6], 0),
    };
    if (bvh) {
        hit.face = { normal: bvh._readFaceNormal(faceIndex) };
    }
    return hit;
}

function _syncGeometryWasm(geometry) {
    if (!geometry?.attributes?.position) return;
    geometry._w = new WebBufferGeometry();
    for (const [name, attr] of Object.entries(geometry.attributes || {})) {
        if (attr?.array) {
            const arr = attr.array instanceof Float32Array ? attr.array : new Float32Array(attr.array);
            geometry._w.setAttribute(name, new WebBufferAttribute(arr, attr.itemSize || 3));
            geometry.attributes[name] = attr;
        }
    }
    const idx = geometry.index?.array || geometry._indexAttr?.array;
    if (idx?.length) {
        const u32 = idx instanceof Uint32Array ? idx : new Uint32Array(idx);
        geometry._w.setIndex(u32);
        geometry._indexAttr = new BufferAttribute(u32, 1);
    }
}

function _resolveWasmGeometry(geometry) {
    if (!geometry?._w) return null;
    if (typeof geometry._w.toBufferGeometry === 'function') {
        return geometry._w.toBufferGeometry();
    }
    return geometry._w;
}

export class ExtendedTriangle extends Triangle {
    constructor(a, b, c) {
        super(a, b, c);
        this.needsUpdate = true;
    }

    copy(tri) {
        super.copy(tri);
        this.needsUpdate = true;
        return this;
    }

    intersectsTriangle(other, targetEdge = new Line3(), coplanar = false) {
        const plane = this.getPlane(new Plane());
        const dA = plane.distanceToPoint(other.a);
        const dB = plane.distanceToPoint(other.b);
        const dC = plane.distanceToPoint(other.c);
        const eps = 1e-10;
        if (dA > eps && dB > eps && dC > eps) return false;
        if (dA < -eps && dB < -eps && dC < -eps) return false;

        const plane2 = other.getPlane(new Plane());
        const eA = plane2.distanceToPoint(this.a);
        const eB = plane2.distanceToPoint(this.b);
        const eC = plane2.distanceToPoint(this.c);
        if (eA > eps && eB > eps && eC > eps) return false;
        if (eA < -eps && eB < -eps && eC < -eps) return false;

        const edge = targetEdge;
        const pts = [other.a, other.b, other.c];
        let hits = 0;
        for (let i = 0; i < 3; i++) {
            const s = pts[i];
            const e = pts[(i + 1) % 3];
            const line = new Line3(s, e);
            const hit = plane.intersectLine(line, new Vector3());
            if (hit && hit.distanceTo(e) > eps) {
                if (hits === 0) edge.start.copy(hit);
                else edge.end.copy(hit);
                hits++;
            }
        }
        return hits >= 2 || coplanar;
    }
}

/**
 * BVH acceleration structure for a BufferGeometry.
 */
export class MeshBVH {
    constructor(geometry, options = {}) {
        _requireMeshBvh();
        this.geometry = geometry;
        if (options._skipBuild) return;
        _syncGeometryWasm(geometry);
        const wasmGeom = _resolveWasmGeometry(geometry);
        if (!wasmGeom) {
            throw new Error('MeshBVH requires geometry with wasm backing');
        }
        const maxDepth = options.maxDepth ?? 40;
        const maxLeafTris = options.maxLeafTris ?? options.maxLeafSize ?? 10;
        const strategy = options.strategy ?? CENTER;
        const offset = options.offset ?? 0;
        const count = options.count ?? 0;
        const indirect = options.indirect ?? false;
        this._w = WebMeshBvh.newWithOptionsFull(wasmGeom, maxDepth, maxLeafTris, strategy, offset, count, indirect);
        this.indirect = indirect;
        geometry.boundsTree = this;
    }

    static serialize(bvh, { cloneBuffers = true } = {}) {
        const parts = bvh._w.serialize();
        const version = parts[0];
        const nodeBuffer = cloneBuffers ? parts[1].slice() : parts[1];
        const triangleOrder = cloneBuffers ? parts[2].slice() : parts[2];
        const triangleIndices = cloneBuffers ? parts[3].slice() : parts[3];
        const positions = cloneBuffers ? parts[4].slice() : parts[4];
        return { version, nodeBuffer, triangleOrder, triangleIndices, positions };
    }

    static deserialize(data, geometry) {
        _requireMeshBvh();
        const bvh = new MeshBVH(geometry, { _skipBuild: true });
        bvh._w = WebMeshBvh.deserialize(
            data.version,
            data.nodeBuffer,
            data.triangleOrder,
            data.triangleIndices,
            data.positions,
        );
        geometry.boundsTree = bvh;
        return bvh;
    }

    refit() {
        const pos = this.geometry?.attributes?.position?.array;
        if (pos) this._w.refit(pos);
        // The geometry's wasm build carries the BVH: re-take it.
        this.geometry?._bump?.();
    }

    intersectsBox(box) {
        const min = box.min || box;
        const max = box.max || box;
        return this._w.intersectsBox(min.x, min.y, min.z, max.x, max.y, max.z);
    }

    intersectsSphere(sphere) {
        const c = sphere.center || sphere;
        const r = sphere.radius ?? 0;
        return this._w.intersectsSphere(c.x, c.y, c.z, r);
    }

    closestPointToPoint(point, target = new Vector3()) {
        const packed = this._w.closestPointToPoint(point.x, point.y, point.z);
        target.set(packed[0], packed[1], packed[2]);
        return { point: target, distance: packed[3], faceIndex: packed[4] | 0 };
    }

    raycast(ray, near = 0, far = Infinity) {
        const packed = this._w.raycast(
            ray.origin.x, ray.origin.y, ray.origin.z,
            ray.direction.x, ray.direction.y, ray.direction.z,
            near, far,
        );
        const hits = [];
        for (let i = 0; i < packed.length; i += 7) {
            hits.push(_unpackHit(packed, i, this));
        }
        return hits;
    }

    raycastFirst(ray, sideOrNear = DoubleSide, far = Infinity) {
        let side = DoubleSide;
        let near = 0;
        let farVal = far;
        if (sideOrNear === FrontSide || sideOrNear === BackSide || sideOrNear === DoubleSide) {
            side = sideOrNear;
        } else {
            near = sideOrNear;
            farVal = far;
        }
        const packed = this._w.raycastFirst(
            ray.origin.x, ray.origin.y, ray.origin.z,
            ray.direction.x, ray.direction.y, ray.direction.z,
            near, farVal, side,
        );
        if (!packed.length) return null;
        return _unpackHit(packed, 0, this);
    }

    resolveTriangleIndex(index) {
        const resolved = this._w.resolveTriangleIndex(index);
        return resolved < 0 ? index : resolved;
    }

    _readFaceNormal(faceIndex) {
        const triFlat = this._w.triangleIndices();
        const positions = this._w.positions();
        const base = faceIndex * 3;
        const ia = triFlat[base];
        const ib = triFlat[base + 1];
        const ic = triFlat[base + 2];
        const read = (vi) => new Vector3(positions[vi * 3], positions[vi * 3 + 1], positions[vi * 3 + 2]);
        const A = read(ia);
        const B = read(ib);
        const C = read(ic);
        return new Vector3().subVectors(B, A).cross(new Vector3().subVectors(C, A)).normalize();
    }

    bvhcast(otherBvh, matrixToLocal, callbacks = {}) {
        const mat = matrixToLocal?.elements
            ? (matrixToLocal.elements.length === 16 ? matrixToLocal : new Matrix4().fromArray(matrixToLocal.elements))
            : new Matrix4();
        const pairs = this._w.bvhcast(otherBvh._w, mat.elements);
        if (!callbacks.intersectsTriangles) {
            return pairs.length > 0;
        }

        const indexAttr1 = this.geometry.index;
        const positionAttr1 = this.geometry.attributes.position;
        const indexAttr2 = otherBvh.geometry.index;
        const positionAttr2 = otherBvh.geometry.attributes.position;
        const tri1 = new ExtendedTriangle();
        const tri2 = new ExtendedTriangle();

        const assignTri = (tri, orderIdx, bvh, indexAttr, positionAttr, matrix) => {
            const ti = bvh.indirect ? bvh.resolveTriangleIndex(orderIdx) : orderIdx;
            const i3 = ti * 3;
            const i0 = indexAttr.getX(i3);
            const i1 = indexAttr.getX(i3 + 1);
            const i2 = indexAttr.getX(i3 + 2);
            tri.a.fromBufferAttribute(positionAttr, i0);
            tri.b.fromBufferAttribute(positionAttr, i1);
            tri.c.fromBufferAttribute(positionAttr, i2);
            if (matrix) {
                tri.a.applyMatrix4(matrix);
                tri.b.applyMatrix4(matrix);
                tri.c.applyMatrix4(matrix);
            }
            tri.needsUpdate = true;
        };

        let found = false;
        for (let i = 0; i < pairs.length; i += 2) {
            const ia = pairs[i];
            const ib = pairs[i + 1];
            assignTri(tri1, ia, this, indexAttr1, positionAttr1, null);
            assignTri(tri2, ib, otherBvh, indexAttr2, positionAttr2, mat);
            if (callbacks.intersectsTriangles(tri1, tri2, ia, ib)) {
                found = true;
            }
        }
        return found;
    }

    getBoundingBox() {
        const buf = this._w.nodeBuffer();
        if (!buf.length) return new BvhBox3(0, 0, 0, 0, 0, 0);
        return new BvhBox3(buf[0], buf[1], buf[2], buf[3], buf[4], buf[5]);
    }

    shapecast(callbacks) {
        const buffer = this._w.nodeBuffer();
        const triFlat = this._w.triangleIndices();
        const positions = this._w.positions();
        const triOrder = this._w.triangleOrder();

        const readVec3 = (vi) => {
            const b = vi * 3;
            return new Vector3(positions[b], positions[b + 1], positions[b + 2]);
        };

        const intersectLeaf = (offset, count, contained, depth, nodeIndex) => {
            for (let i = 0; i < count; i++) {
                const orderIdx = triOrder[offset + i];
                const base = orderIdx * 3;
                const ia = triFlat[base];
                const ib = triFlat[base + 1];
                const ic = triFlat[base + 2];
                const a = readVec3(ia);
                const b = readVec3(ib);
                const c = readVec3(ic);
                const tri = new Triangle(a, b, c);
                tri.a = a;
                tri.b = b;
                tri.c = c;
                if (callbacks.intersectsTriangle?.(tri, orderIdx, contained, depth, nodeIndex)) {
                    return true;
                }
            }
            return false;
        };

        const traverse = (nodeIndex, depth) => {
            const base = nodeIndex * 8;
            const box = new BvhBox3(
                buffer[base], buffer[base + 1], buffer[base + 2],
                buffer[base + 3], buffer[base + 4], buffer[base + 5],
            );
            const meta0 = buffer[base + 6];
            const meta1 = buffer[base + 7];
            const isLeaf = meta0 < 0;

            const boundsResult = callbacks.intersectsBounds?.(
                box, isLeaf, undefined, depth, nodeIndex,
            ) ?? INTERSECTED;

            if (boundsResult === NOT_INTERSECTED) return false;

            if (isLeaf) {
                const offset = (-meta0 - 1) | 0;
                const count = meta1 | 0;
                return intersectLeaf(offset, count, boundsResult === CONTAINED, depth, nodeIndex);
            }

            if (boundsResult === CONTAINED) {
                return intersectSubtree(nodeIndex, depth);
            }

            const left = meta0 | 0;
            const right = meta1 | 0;
            if (callbacks.boundsTraverseOrder) {
                const leftBox = _childBox(buffer, left);
                const rightBox = _childBox(buffer, right);
                const leftScore = callbacks.boundsTraverseOrder(leftBox);
                const rightScore = callbacks.boundsTraverseOrder(rightBox);
                const first = leftScore < rightScore ? left : right;
                const second = first === left ? right : left;
                if (traverse(first, depth + 1)) return true;
                if (traverse(second, depth + 1)) return true;
                return false;
            }
            if (traverse(left, depth + 1)) return true;
            if (traverse(right, depth + 1)) return true;
            return false;
        };

        const intersectSubtree = (nodeIndex, depth) => {
            const base = nodeIndex * 8;
            const meta0 = buffer[base + 6];
            const meta1 = buffer[base + 7];
            if (meta0 < 0) {
                const offset = (-meta0 - 1) | 0;
                const count = meta1 | 0;
                return intersectLeaf(offset, count, true, depth, nodeIndex);
            }
            return intersectSubtree(meta0 | 0, depth + 1) ||
                intersectSubtree(meta1 | 0, depth + 1);
        };

        return traverse(0, 0);
    }
}

function _childBox(buffer, nodeIndex) {
    const base = nodeIndex * 8;
    return new BvhBox3(
        buffer[base], buffer[base + 1], buffer[base + 2],
        buffer[base + 3], buffer[base + 4], buffer[base + 5],
    );
}

export function computeBoundsTree(options = {}) {
    _syncGeometryWasm(this);
    const maxDepth = options.maxDepth ?? 40;
    const maxLeafTris = options.maxLeafTris ?? options.maxLeafSize ?? 10;
    const strategy = options.strategy ?? CENTER;
    const offset = options.offset ?? 0;
    const count = options.count ?? 0;
    const indirect = options.indirect ?? false;
    const bvh = new MeshBVH(this, { maxDepth, maxLeafTris, strategy, offset, count, indirect });
    return bvh;
}

export function disposeBoundsTree() {
    if (this.boundsTree) {
        this.boundsTree = null;
    }
    this._w?.disposeBoundsTree?.();
}

/**
 * three-mesh-bvh's `acceleratedRaycast`: a mesh whose geometry has a
 * `boundsTree` is cast through it — in Rust, where the geometry's wasm build
 * carries the same BVH — with the same per-triangle test, side, groups and
 * material array, draw range and hit record as the plain `Mesh.raycast`.
 * With `raycaster.firstHitOnly` the mesh reports only its nearest hit, found
 * by the BVH's closest-hit traversal. A mesh without a `boundsTree` takes the
 * original `Mesh.raycast`. Unlike three-mesh-bvh's default (non-`indirect`)
 * build, the wasm BVH leaves the index alone, so `faceIndex` names the
 * triangle in the geometry as given.
 */
export function acceleratedRaycast(raycaster, intersects) {
    if (!this.geometry?.boundsTree?._w) return _origMeshRaycast.call(this, raycaster, intersects);
    _meshRaycastInternals.cast(raycaster, this, intersects, raycaster.firstHitOnly === true);
}

/** The shim's own `Mesh.raycast`, captured before `installMeshBvh` patches it. */
const _origMeshRaycast = Mesh.prototype.raycast;

/**
 * Bake static meshes under `root` into one merged BufferGeometry.
 */
export class StaticGeometryGenerator {
    constructor(root) {
        this.object = root;
        this.attributes = ['position'];
        this.useGroups = false;
    }

    generate() {
        const geoms = [];
        const visit = (node) => {
            if (node.visible === false) return;
            if (node.isMesh && !node.isSkinnedMesh) {
                const clone = _cloneGeometryAsBuffer(node.geometry);
                if (!clone) return;
                // three-mesh-bvh reads `matrixWorld` as it stands (no update).
                const matrixWorld = node.matrixWorld;
                clone.applyMatrix4(matrixWorld);
                geoms.push(clone);
            }
            for (const c of node.children || node._children || []) visit(c);
        };
        visit(this.object);

        if (!geoms.length) {
            return new BufferGeometry();
        }
        if (geoms.length === 1) {
            return geoms[0];
        }
        return _mergeBufferGeometries(geoms);
    }
}

function _bufferGeometryFromWasm(wasmGeom) {
    const out = new BufferGeometry();
    out._w = wasmGeom;
    const pos = wasmGeom.getAttributeArray('position');
    if (pos) {
        const itemSize = wasmGeom.getAttributeItemSize('position') || 3;
        out.setAttribute('position', new BufferAttribute(new Float32Array(pos), itemSize));
    }
    const normal = wasmGeom.getAttributeArray('normal');
    if (normal) {
        const itemSize = wasmGeom.getAttributeItemSize('normal') || 3;
        out.setAttribute('normal', new BufferAttribute(new Float32Array(normal), itemSize));
    }
    const uv = wasmGeom.getAttributeArray('uv');
    if (uv) {
        const itemSize = wasmGeom.getAttributeItemSize('uv') || 2;
        out.setAttribute('uv', new BufferAttribute(new Float32Array(uv), itemSize));
    }
    const index = wasmGeom.getIndexArray?.();
    if (index?.length) {
        out.setIndex(new Uint32Array(index));
    }
    return out;
}

/** Built-in primitives (BoxGeometry, etc.) expose WebGeometry — convert for BVH/merge. */
function _geometryAsBuffer(geometry) {
    if (geometry?.attributes?.position) {
        return geometry;
    }
    if (geometry?._w?.toBufferGeometry) {
        return _bufferGeometryFromWasm(geometry._w.toBufferGeometry());
    }
    return null;
}

function _cloneGeometryAsBuffer(src) {
    const buf = _geometryAsBuffer(src);
    if (!buf) return null;
    const clone = new BufferGeometry();
    for (const name of Object.keys(buf.attributes)) {
        const attr = buf.attributes[name];
        clone.setAttribute(name, new BufferAttribute(new Float32Array(attr.array), attr.itemSize || 3));
    }
    if (buf.index) {
        clone.setIndex(new Uint32Array(buf.index.array));
    }
    return clone;
}

function _mergeBufferGeometries(geoms) {
    const wasmGeoms = geoms.map((g) => {
        _syncGeometryWasm(g);
        return g._w;
    });
    const merged = mergeGeometries(wasmGeoms);
    return _bufferGeometryFromWasm(merged);
}

/**
 * Patch threers prototypes for three-mesh-bvh compatibility.
 */
export function installMeshBvh(THREE = {}) {
    _requireMeshBvh();
    const BG = THREE.BufferGeometry || BufferGeometry;
    const M = THREE.Mesh || Mesh;
    if (!BG.prototype.computeBoundsTree) {
        BG.prototype.computeBoundsTree = computeBoundsTree;
    }
    if (!BG.prototype.disposeBoundsTree) {
        BG.prototype.disposeBoundsTree = disposeBoundsTree;
    }
    M.prototype.raycast = acceleratedRaycast;

    return { MeshBVH, StaticGeometryGenerator, acceleratedRaycast, computeBoundsTree, disposeBoundsTree, GenerateMeshBVHWorker };
}

/**
 * Async BVH builder (yields before blocking wasm build; API-compatible with three-mesh-bvh worker).
 */
export class GenerateMeshBVHWorker {
    constructor() {
        this._running = false;
    }

    async generate(geometry, options = {}) {
        await new Promise((r) => setTimeout(r, 0));
        this._running = true;
        try {
            return new MeshBVH(geometry, options);
        } finally {
            this._running = false;
        }
    }

    dispose() {
        this._running = false;
    }
}

export default {
    MeshBVH,
    StaticGeometryGenerator,
    acceleratedRaycast,
    computeBoundsTree,
    disposeBoundsTree,
    installMeshBvh,
    GenerateMeshBVHWorker,
    NOT_INTERSECTED,
    INTERSECTED,
    CONTAINED,
    CENTER,
    AVERAGE,
    SAH,
};
